export const LUA_HEADER = [
  '-- This file is auto-generated by TOLU. Do not edit manually.',
  '-- https://github.com/laot7490/tolu',
].join('\n')

export type LuaClass = {
  name: string
  fields: Array<{ name: string; type: string }>
}

export function emitLua(classes: LuaClass[]): string {
  const blocks = classes.map((cls) => {
    const lines = [`---@class ${cls.name}`]
    for (const field of cls.fields) {
      lines.push(`---@field ${field.name} ${field.type}`)
    }
    return lines.join('\n')
  })

  return `${LUA_HEADER}\n\n${blocks.join('\n\n')}\n`
}
